import{_ as a,o as r,c as e,a3 as d}from"./chunks/framework.Dj4Lt7vj.js";const b=JSON.parse('{"title":"AI 设置与智能程度","description":"","frontmatter":{"title":"AI 设置与智能程度"},"headers":[],"relativePath":"solution/agents.md","filePath":"solution/agents.md","lastUpdated":1787948622000}'),o={name:"solution/agents.md"};function n(s,t,i,l,h,p){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="ai-设置与智能程度" tabindex="-1">AI 设置与智能程度 <a class="header-anchor" href="#ai-设置与智能程度" aria-label="Permalink to &quot;AI 设置与智能程度&quot;">​</a></h1><p>「AI 设置」是方案的核心模块：告诉 AI 它是谁、该怎么说话、能用哪些工具、用多大力气回答。</p><h2 id="回复设定" tabindex="-1">回复设定 <a class="header-anchor" href="#回复设定" aria-label="Permalink to &quot;回复设定&quot;">​</a></h2><p>默认回复设定对所有消息生效。写清楚三件事：</p><ol><li><strong>店铺背景</strong>：卖什么、主要客群。</li><li><strong>语气要求</strong>：亲切、简洁、是否用表情等。</li><li><strong>边界</strong>：哪些话不能说，哪些问题必须转人工。</li></ol><p>写法上就当是在给新来的客服写岗前说明，不需要特殊格式。</p><h2 id="智能程度" tabindex="-1">智能程度 <a class="header-anchor" href="#智能程度" aria-label="Permalink to &quot;智能程度&quot;">​</a></h2><p>智能程度分四档，决定 AI 回答时投入的算力——更聪明也更慢、更费点数：</p><table tabindex="0"><thead><tr><th>档位</th><th>说明</th></tr></thead><tbody><tr><td>快速</td><td>回复最快、最省点数。适合催发货、问库存这类一问一答的简单咨询</td></tr><tr><td>适中</td><td>速度与效果平衡，日常客服推荐。遇到稍复杂的问题会自动多花一点力气</td></tr><tr><td>高级</td><td>复杂问题答得更稳，回复更慢、更费点数。适合规格比对、售后纠纷等需要推敲的场景</td></tr><tr><td>极致</td><td>疑难问题尽最大努力作答，回复最慢、最费点数。建议只用在高价值或易起争议的会话</td></tr></tbody></table><p>不确定就选<strong>适中</strong>。上了量之后再根据消耗和效果微调。</p><h2 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h2><p>工具决定 AI 除了「说话」还能做什么。可以逐个开关：</p><table tabindex="0"><thead><tr><th>工具</th><th>作用</th></tr></thead><tbody><tr><td>查询知识库</td><td>回答前检索绑定的知识库资料</td></tr><tr><td>转人工</td><td>判断需要人工时发起转接，见<a href="/aicare-docs/solution/transfer">转人工设置</a></td></tr><tr><td>查询表格</td><td>从查询表里查数据，比如库存价格表</td></tr><tr><td>登记记录</td><td>把顾客需求写进登记表，比如售后登记</td></tr></tbody></table><p>关掉「转人工」后 AI 将不会主动转接，请确认你的场景确实不需要。</p><h2 id="情景配置" tabindex="-1">情景配置 <a class="header-anchor" href="#情景配置" aria-label="Permalink to &quot;情景配置&quot;">​</a></h2><p>「AI 设置」页面右上角的「情景配置」入口，可以为不同客户情景配置专用的回复设定和触发规则——比如售后问题单独一套话术。详见<a href="/aicare-docs/solution/triggers">情景与触发规则</a>。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>改了设定多久生效？</strong> 保存后新会话立即生效，进行中的会话按新设定继续。</p><p><strong>四档智能程度分别用什么模型？</strong> 档位只承诺快慢、成本和适用场景，不绑定具体模型。平台会持续调整底层模型来保证各档位的体验。</p>',19)])])}const u=a(o,[["render",n]]);export{b as __pageData,u as default};
